draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw book
  ctx.fillStyle = '#663300';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2+70, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2, H/2+120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+90);
  ctx.lineTo(W/2-30, H/2+150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+90);
  ctx.lineTo(W/2+30, H/2+150);
  ctx.stroke();

  // draw wisdom lines
  ctx.lineWidth = 2;
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2-40+i*10, H/2-40+Math.sin(t+i)*20);
    ctx.lineTo(W/2-40+i*10, H/2-20+Math.sin(t+i)*20);
    ctx.stroke();
  }

  ctx.restore();
}
